from langchain.agents import create_agent

def lookup_city(city: str) -> str:
    """Return a short note about a city."""
    return f"{city}: a city worth exploring."

agent = create_agent(
    model="openai:gpt-5.5",   # 换成你账号可用的 provider:model
    tools=[lookup_city],
    system_prompt="You are a concise research assistant.",
)

result = agent.invoke({
    "messages": [{"role": "user", "content": "Look up Kyoto."}]
})
print(result["messages"][-1].content)

result = agent.invoke({
    "messages": [{"role": "user", "content": "Look up Kyoto."}]
})
for message in result["messages"]:
    print(type(message).__name__, message.content_blocks)
    for call in getattr(message, "tool_calls", []):
        print("  tool_call:", call["name"], call["args"], call["id"])

from langchain.tools import tool

@tool
def search_docs(query: str, limit: int = 3) -> str:
    """Search the local docs and return up to `limit` labelled passages.

    Use this when the user asks about material in the provided
    knowledge base. Do not use it for live web search.
    """
    docs = retriever.invoke(query)
    return "\n\n".join(
        f"[{d.metadata.get('source', 'unknown')}] {d.page_content}"
        for d in docs[:limit]
    )

