from langchain.tools import tool

@tool
def search_docs(query: str) -> str:
    """Search the local knowledge base. Return labelled passages."""
    docs = retriever.invoke(query)
    return "\n\n".join(
        f"[{d.metadata.get('source', 'unknown')}] {d.page_content}"
        for d in docs[:4]
    )

for chunk in agent.stream(
    {"messages": [{"role": "user", "content": "Summarize the docs."}]},
    stream_mode="messages",
):
    token, metadata = chunk
    if token.content:
        print(token.content, end="", flush=True)

CASES = [
    {"q": "Find the refund policy.", "must_call": "search_docs"},
    {"q": "What is 17 * 23?", "must_call": "calculator"},
]

for case in CASES:
    out = agent.invoke({
        "messages": [{"role": "user", "content": case["q"]}]
    })
    calls = [
        c["name"]
        for m in out["messages"]
        for c in getattr(m, "tool_calls", [])
    ]
    assert case["must_call"] in calls, (case["q"], calls)
